out.append(("crash_date missing/impossible/default within planned date range", "0 missing; DATE type excludes impossible values; no date default falls within the specified year range")); Path("out").mkdir(exist_ok=True); f=open("out/check_1.csv","w",newline=""); w=csv.writer(f); w.writerow(["fact","value"]); w.writerows(out); f.close(); print("\n".join(f"{a}: {b}" for a,b in out))'

